SELECT production_date, shift, wet_end_id, quality_id AS grade, sum(lineal_ft) AS feet, sum(seconds - stop_seconds) / 60 AS run_min FROM setups WHERE production_date BETWEEN ? AND ? AND setup_id NOT IN (?) GROUP BY ALL ORDER BY production_date, shift, wet_end_id, grade;
SELECT shift, kind, reason, count(*) AS stops, sum(seconds) / 60 AS minutes FROM stops WHERE production_date BETWEEN ? AND ? GROUP BY ALL ORDER BY shift, kind, reason;
SELECT quality_id AS grade, count(*) AS setups, sum(lineal_ft) AS feet, sum(seconds - stop_seconds) / 60 AS run_min FROM setups WHERE production_date BETWEEN ? AND ? AND seconds - stop_seconds >= ? * 60 GROUP BY quality_id ORDER BY quality_id;
